$filePath = "X:\code\copilot-worktrees\P06\cirvine-msft-expert-enigma\assets\due.txt"
$content = Get-Content -Raw -Path $filePath
$lines = @($content -split "`n")

# Remove empty trailing line if file ends with newline
if ($lines[-1] -eq "") {
    $lines = $lines[0..($lines.Count - 2)]
}

# Get the actual file bytes to check final newline
