Write-Host "Contains 'DUE': $hasDUE"

# Check allowed characters
$allowedPattern = "^[ A-Z0-9+|/\\\_\*\.#\(\):=\-]+$"
$invalidLines = @()
foreach ($i in 0..($lines.Count - 1)) {
    if ($lines[$i] -notmatch $allowedPattern) {
        $invalidLines += "Line $($i+1): $($lines[$i])"
    }
}
Write-Host "Invalid character usage: $($invalidLines.Count -gt 0)"
if ($invalidLines.Count -gt 0) {
    $invalidLines | ForEach-Object { Write-Host "  $_" }
}

Write-Host ""
Write-Host "=== RESULT ==="
if ($lines.Count -eq 12 -and $endsWithNewline -and $minLen -ge 20 -and $maxLen -le 48 -and $hasTrailingWS.Count -eq 0 -and $hasDUE -and $invalidLines.Count -eq 0) {
    Write-Host "✓ ALL CONSTRAINTS SATISFIED"
} else {
    Write-Host "✗ CONSTRAINT VIOLATIONS DETECTED"
}

