    $len = $lines[$i].Length
    Write-Host "  Line $($i+1): $len chars"
}

# Check for DUE substring
Write-Host ""
$dueLines = @()
foreach ($i in 0..($lines.Count - 1)) {
    if ($lines[$i] -contains "DUE" -or $lines[$i] | Select-String "DUE") {
        $dueLines += $i + 1
    }
}
if ($dueLines.Count -gt 0) {
    Write-Host "Contains 'DUE': YES (line(s): $($dueLines -join ', '))"
} else {
    Write-Host "Contains 'DUE': CHECKING..."
    foreach ($i in 0..($lines.Count - 1)) {
        if ($lines[$i].Contains("DUE")) {
            Write-Host "  Found at line $($i + 1)"
        }
    }
}

# Check line endings
$hasCRLF = $content -match "`r`n"
$hasLFOnly = -not $hasCRLF -and $content -match "`n"
