    if ($lines[$i] -match '\s$') {
        Write-Host "Line $($i+1) has trailing whitespace"
        $trailingWS = $true
    }
}
if (-not $trailingWS) {
    Write-Host "Trailing whitespace: NONE"
}

# Check file ends with single newline
$lastByte = $bytes[-1]
Write-Host "Last byte: $lastByte (10=LF, 13=CR, expected: 10)"

# Check allowed characters
Write-Host ""
Write-Host "Character validation:"
$allowed = @(' ') + @(65..90) + @(48..57) + @('+'.toCharArray()) + @('|'.toCharArray()) + @('/'.toCharArray()) + @('\'.toCharArray()) + @('_'.toCharArray()) + @('*'.toCharArray()) + @('.'.toCharArray()) + @('#'.toCharArray()) + @('('.toCharArray()) + @(')'.toCharArray()) + @(':'.toCharArray()) + @('='.toCharArray()) + @('-'.toCharArray())

