        $code = [int][char]$ch
        if ($code -lt 32 -or $code -gt 126 -or ($code -ge 97 -and $code -le 122) -or ($code -ge 33 -and $code -le 126 -and -not @([int][char]'+', [int][char]'|', [int][char]'/', [int][char]'\', [int][char]'_', [int][char]'*', [int][char]'.', [int][char]'#', [int][char]'(', [int][char]')', [int][char]':', [int][char]'=', [int][char]'-', [int][char]' ').Contains($code) -and -not ($code -ge 48 -and $code -le 57) -and -not ($code -ge 65 -and $code -le 90))) {
