            $violations++
        }
    }
}
if ($violations -eq 0) {
    Write-Host "  All characters allowed"
}

Write-Host ""
Write-Host "=== SUMMARY ==="
$valid = $lines.Count -eq 12 -and $minLen -ge 20 -and $maxLen -le 48 -and $lastByte -eq 10 -and $hasLFOnly -and -not $trailingWS -and $violations -eq 0
